Sass layer defaults, declarations, and rules now use a `sass_layer_list` class. This class allows for these particular items to be processed differently than a regular named list.

The main gain is users can remove items that have been flagged using `list(key = sass_removable(x))`. 

This still follows the main setup of a named list, however, if the value (of the key/value pair) is a removable list only the content of the removable list is processed and the key is ignored.

Open question:
- [x] Should ALL `list()` objects process / behave like a `sass_layer_list()` objects?
  * No. removable items should only be supported in layer rules

This would allow for:

```r
x <- list(color = "blue !default", mykey = sass_removable(list(color = "red")))
str(x)
#> List of 2
#>  $ color: chr "blue !default"
#>  $ mykey:List of 1
#>   ..$ color: chr "red"
#>   ..- attr(*, "class")= chr [1:2] "sass_removable" "list"

# bad
as_sass(x)
#> /* Sass */
#> $color: blue !default;
#> $mykey: $color: red;;

# expected
as_sass(as_sass_layer_list(x))
#> /* Sass */
#> $color: blue !default;
#> $color: red;
```


-------------------------

Demo of `sass_layers_remove()`

```
blue <- list(color = "blue !default")
red <- list(color = "red !default")
green <- list(color = "green !default")
core <- sass_layer(
  defaults = blue,
  declarations = "@function my_invert($color, $amount: 100%) {
    $inverse: change-color($color, $hue: hue($color) + 180);
    @return mix($inverse, $color, $amount);
  }",
  rules = "body { background-color: $color; color: my_invert($color); }"
)
layers_big <-
  sass_layers(
    sass_layers(core, red = ":root{ --color: #{$color}; }"),
    green = sass_layer(green)
  )
layers_big
#> /* Sass Layers: red, green */
#> $color: green !default;
#> $color: blue !default;
#> @function my_invert($color, $amount: 100%) {
#>     $inverse: change-color($color, $hue: hue($color) + 180);
#>     @return mix($inverse, $color, $amount);
#>   }
#> body { background-color: $color; color: my_invert($color); }
#> :root{ --color: #{$color}; }
#> /* *** */

layers_slim <- sass_layers_remove(layers_big, "red")
layers_slim
#> /* Sass Layers: green */
#> $color: green !default;
#> $color: blue !default;
#> @function my_invert($color, $amount: 100%) {
#>     $inverse: change-color($color, $hue: hue($color) + 180);
#>     @return mix($inverse, $color, $amount);
#>   }
#> body { background-color: $color; color: my_invert($color); }
#> /* *** */
```
